function rowFilledOk(r) {
  if (!r) return false;
  if (r.success === true) return true;
  const n = Number(r.fields_filled);
  if (!Number.isNaN(n) && n > 0) return true;
  return /JIS filled/i.test(String(r.message || ''));
}

const res = $input.first().json || {};
const previews = $('Build Batch Payload').first().json.previews || [];
const results = res.results || [];
const updates = [];
const failed = [];

for (const r of results) {
  const idx = typeof r.index === 'number' ? r.index : parseInt(r.index, 10);
  const prev = Number.isNaN(idx) ? null : previews[idx];
  if (rowFilledOk(r) && prev && prev.row_number != null) {
    updates.push({
      json: {
        row_number: prev.row_number,
        jis_uploaded: true,
        jis_uploaded_at: new Date().toISOString(),
        q13: prev.q13 || r.q13 || null,
        _had_warnings: r.success === false,
      },
    });
  } else if (prev) {
    failed.push({
      row_number: prev.row_number ?? null,
      q13: prev.q13 ?? r.q13 ?? null,
      message: r.message || res.message || 'Not filled',
    });
  }
}

const okCount = updates.length;

if (!updates.length) {
  return [{
    json: {
      _skip_update: true,
      jis_uploaded_marked_count: 0,
      batch_success: okCount > 0,
      failed_count: failed.length,
      failed_rows: failed,
      http_error: res.http_error === true,
      message: res.message || 'No rows to mark jis_uploaded on jis tab.',
    },
  }];
}

return updates.map((item, i) => ({
  json: {
    ...item.json,
    _skip_update: false,
    ...(i === 0
      ? {
          jis_uploaded_marked_count: updates.length,
          batch_success: okCount > 0,
          failed_count: failed.length,
          failed_rows: failed,
          http_error: res.http_error === true,
        }
      : {}),
  },
}));

function rowFilledOk(r) {
  if (!r) return false;
  if (r.success === true) return true;
  const n = Number(r.fields_filled);
  if (!Number.isNaN(n) && n > 0) return true;
  return /JIS filled/i.test(String(r.message || ''));
}

const items = $input.all();
const first = items[0]?.json || {};
const prep = $('Prepare jis_uploaded updates').first().json || {};
const batch = $('Log Batch Result').first().json || $('POST fill-jis-batch').first().json || {};
const results = batch.results || [];
const okCount = results.filter(rowFilledOk).length;

const marked =
  prep.jis_uploaded_marked_count ??
  items.filter((i) => i.json.jis_uploaded === true || String(i.json.jis_uploaded).toLowerCase() === 'true').length;

const failedCount = prep.failed_count ?? Math.max(0, results.length - okCount);
const batchOk = marked > 0 || okCount > 0 || first.batch_success === true || prep.batch_success === true;

return [{
  json: {
    ok: batchOk,
    message:
      first.message ||
      prep.message ||
      batch.message ||
      `Marked ${marked} row(s) jis_uploaded; ${failedCount} failed`,
    rows_processed: batch.rows_processed ?? results.length ?? null,
    jis_uploaded_marked_count: marked,
    results_ok_count: okCount,
    results_count: results.length,
    failed_count: failedCount,
    failed_rows: prep.failed_rows || [],
    http_error: prep.http_error === true || batch.http_error === true,
  },
}];

const apptByUprn = {};
for (const item of $input.all()) {
  const r = item.json || {};
  const uprn = String(r.UPRN ?? '').replace(/\D/g, '');
  if (uprn) apptByUprn[uprn] = r;
}
$getWorkflowStaticData('global').apptByUprn = apptByUprn;
return [{
  json: {
    appointment_rows_indexed: Object.keys(apptByUprn).length
  }
}];

const JIS_KEYS = [
  'Q1.1', 'Q1.2', 'Q1.3', 'Q1.4', 'Q1.5', 'Q1.6',
  'Q2.1', 'Q2.2', 'Q3.1', 'Q3.2', 'Q4.1', 'Q4.2', 'Q5.1', 'Q5.2',
  'QS-Task', 'Asbestos Status'
];

function isJisUploaded(v) {
  if (v === true || v === 1) return true;
  const s = String(v ?? '').trim().toLowerCase();
  return s === 'true' || s === 'yes' || s === '1' || s === 'uploaded';
}

function pickUploadedFlag(row) {
  return row.jis_uploaded ?? row['JIS-uploaded'] ?? row['JIS uploaded'] ?? null;
}

const out = [];
let skippedUploaded = 0;

for (const item of $input.all()) {
  const row = item.json || {};
  const q13 = String(row['Q1.3'] ?? '').trim();
  if (!q13) continue;

  if (isJisUploaded(pickUploadedFlag(row))) {
    skippedUploaded++;
    continue;
  }

  const row_data = {};
  for (const k of JIS_KEYS) {
    if (row[k] != null && String(row[k]).trim() !== '') {
      row_data[k] = String(row[k]).trim();
    }
  }
  if (!row_data['Q1.3']) continue;

  out.push({
    json: {
      row_data,
      row_number: row.row_number ?? null,
      q13_preview: q13,
      q12_preview: row_data['Q1.2'] || null
    }
  });
}

if (!out.length) {
  return [{
    json: {
      _message: skippedUploaded
        ? 'No pending jis rows — all with Q1.3 already have jis_uploaded=true'
        : 'No jis rows with Q1.3 set',
      _count: 0,
      skipped_already_uploaded: skippedUploaded
    }
  }];
}
return out;

const APPT_KEYS = [
  'UPRN', '7.1', '7.2', '8.1', '8.2', '9.1', '9.2', '10.1', '10.2', '11.1', '11.2',
  'Trade_1', 'Hours_1', 'Notes_1', 'Trade_2', 'Hours_2', 'Notes_2',
  'Trade_3', 'Hours_3', 'Notes_3', 'Trade_4', 'Hours_4', 'Notes_4',
  'Trade_5', 'Hours_5', 'Notes_5'
];

function normUprn(v) {
  return String(v ?? '').replace(/\D/g, '');
}

function uprnFromQ12(q12) {
  const m = String(q12 ?? '').match(/-\s*(\d{5,})\s*$/);
  return m ? normUprn(m[1]) : '';
}

function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const digits = t.replace(/\D/g, '');
  if (digits.length >= 4) return String(parseInt(digits, 10));
  return t;
}

function cleanAddrKey(str) {
  return String(str || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function addrFromQ12(q12) {
  const m = String(q12 || '').match(/^[^-]+-\s*(.+?)\s*-\s*\d{5,}\s*$/);
  return m ? cleanAddrKey(m[1]) : cleanAddrKey(String(q12 || '').split('-')[0]);
}

const apptByUprn = $getWorkflowStaticData('global').apptByUprn || {};
const corfToWorksId = $getWorkflowStaticData('global').corfToWorksId || {};
const addrToWorksId = $getWorkflowStaticData('global').addrToWorksId || {};
const items = $input.all();
const opts = $('Set API base URL').first().json || {};
const rows = [];
const previews = [];
let resolved = 0;
let missing = 0;

for (const it of items) {
  const row_data = { ...(it.json.row_data || {}) };
  if (!row_data['Q1.3']) continue;

  const uprn = uprnFromQ12(row_data['Q1.2']) || normUprn(row_data.UPRN);
  const ap = uprn ? apptByUprn[uprn] : null;
  if (ap) {
    const appointment_row = {};
    for (const k of APPT_KEYS) {
      if (ap[k] != null && String(ap[k]).trim() !== '') {
        appointment_row[k] = String(ap[k]).trim();
      }
    }
    if (Object.keys(appointment_row).length) {
      row_data.appointment_row = appointment_row;
    }
  }

  const corf = normCorf(row_data['Q1.3']);
  let works_id = corfToWorksId[corf] || '';
  if (!works_id) {
    const addrKey = addrFromQ12(row_data['Q1.2']);
    if (addrKey) works_id = addrToWorksId[addrKey] || '';
  }
  if (works_id) {
    row_data.works_id = works_id;
    resolved += 1;
  } else {
    missing += 1;
  }

  rows.push(row_data);
  previews.push({
    row_number: it.json.row_number,
    q13: it.json.q13_preview,
    q12: it.json.q12_preview,
    uprn,
    works_id: works_id || null,
    has_appointment: Boolean(ap && (ap.Trade_1 || '').toString().trim()),
  });
}

return [{
  json: {
    api_base_url: opts.api_base_url || opts.ngrok_base_url,
    contract_id: opts.contract_id || '321129',
    rows,
    row_count: rows.length,
    previews,
    works_id_resolved: resolved,
    works_id_missing: missing,
    use_works_id_navigation: resolved > 0,
  },
}];

const res = $input.first().json || {};
const previews = $('Build Batch Payload').first().json.previews || [];
return [{
  json: {
    success: res.success,
    message: res.message,
    rows_processed: res.rows_processed,
    results: res.results || [],
    previews
  }
}];

function tryParseJson(raw) {
  if (raw == null) return null;
  if (typeof raw === 'object') return raw;
  if (typeof raw !== 'string') return null;
  try { return JSON.parse(raw); } catch (e) { return null; }
}

const errBody = $input.first().json || {};
const previews = $('Build Batch Payload').first().json.previews || [];

let payload =
  tryParseJson(errBody.body) ||
  tryParseJson(errBody.error?.response?.body) ||
  tryParseJson(errBody.error?.message) ||
  tryParseJson(errBody.message) ||
  null;

if (payload && Array.isArray(payload.results)) {
  return [{
    json: {
      success: payload.success === true,
      message: payload.message || 'Batch returned partial results on HTTP error',
      rows_processed: payload.rows_processed ?? payload.results.length,
      results: payload.results,
      previews,
      http_error: true,
    },
  }];
}

const msg =
  errBody.error?.message ||
  errBody.message ||
  errBody.detail ||
  (typeof errBody === 'string' ? errBody : JSON.stringify(errBody)).slice(0, 500);

return [{
  json: {
    success: false,
    message: msg,
    rows_processed: 0,
    results: [],
    previews,
    http_error: true,
  },
}];

function rowFilledOk(r) {
  if (!r) return false;
  if (r.success === true) return true;
  const n = Number(r.fields_filled);
  if (!Number.isNaN(n) && n > 0) return true;
  return /JIS filled/i.test(String(r.message || ''));
}

const sd = $getWorkflowStaticData('global');
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/London' });
if (sd.jisDailyDate !== today) {
  sd.jisDailyDate = today;
  sd.jisDailyLog = [];
}
const log = sd.jisDailyLog || [];
const seen = new Set(log.map((e) => `${e.q13}::${e.works_id}`));

const batch = $('Log Batch Result').first().json || {};
const previews = batch.previews || [];
const results = batch.results || [];

for (const r of results) {
  if (!rowFilledOk(r)) continue;
  const idx = typeof r.index === 'number' ? r.index : parseInt(r.index, 10);
  const prev = Number.isNaN(idx) ? null : previews[idx];
  const q13 = String(prev?.q13 || r.q13 || '').trim();
  const works_id = String(prev?.works_id || r.works_id || '').trim();
  if (!q13) continue;
  const key = `${q13}::${works_id}`;
  if (seen.has(key)) continue;
  seen.add(key);
  log.push({
    at: new Date().toISOString(),
    q13,
    works_id,
    q12: prev?.q12 || '',
    row_number: prev?.row_number ?? null,
    status: 'JIS filled on EasyBOP',
  });
}
sd.jisDailyLog = log;
return $input.all();

function bodyFrom(resp) {
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = {}; }
  }
  if (body && body.body && body.items === undefined && body.total === undefined) {
    body = body.body;
  }
  return body || {};
}

function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const digits = t.replace(/\D/g, '');
  if (digits.length >= 4) return String(parseInt(digits, 10));
  return t;
}

function cleanAddrKey(str) {
  return String(str || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}

const resp = $input.first().json || {};
const data = bodyFrom(resp);
const items = Array.isArray(data.items) ? data.items : [];

const corfToWorksId = {};
const addrToWorksId = {};
for (const item of items) {
  const wid = String(item.works_id || '').trim();
  if (!wid) continue;
  const corf = normCorf(item.client_order_reference || '');
  if (corf) corfToWorksId[corf] = wid;
  const addr = cleanAddrKey(item.address || '');
  if (addr) addrToWorksId[addr] = wid;
}

const sd = $getWorkflowStaticData('global');
sd.corfToWorksId = corfToWorksId;
sd.addrToWorksId = addrToWorksId;

return [{
  json: {
    works_index_total: data.total ?? items.length,
    works_index_ok: data.success === true,
    corf_map_size: Object.keys(corfToWorksId).length,
    message: data.message || `Indexed ${items.length} works (paginated scrape)`,
  },
}];

function esc(t) {
  return String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const sd = $getWorkflowStaticData('global');
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/London' });
const logs = (sd.jisDailyDate === today && Array.isArray(sd.jisDailyLog)) ? sd.jisDailyLog : [];
const reportDate = new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/London' });
const logo = 'https://jeffway.co.uk/wp-content/uploads/2025/05/jeffway-group-1.svg';

let jobRows = '';
if (logs.length) {
  jobRows = logs.map((l, i) => '<tr>'
    + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(i + 1) + '</td>'
    + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.q13 || '-') + '</td>'
    + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.works_id || '-') + '</td>'
    + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.q12 || '-') + '</td>'
    + '<td style="padding:8px;border-bottom:1px solid #eee;color:#15803d;font-weight:bold;">' + esc(l.status || 'Filled') + '</td>'
    + '</tr>').join('');
} else {
  jobRows = '<tr><td colspan="5" style="padding:16px;text-align:center;color:#666;">No JIS forms filled on EasyBOP today.</td></tr>';
}

const html = [
  '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>',
  '<body style="margin:0;padding:0;font-family:Arial,sans-serif;background:#f4f4f4;">',
  '<table width="100%" style="background:#f4f4f4;padding:20px;"><tr><td align="center">',
  '<table width="760" style="background:#fff;border-radius:8px;overflow:hidden;">',
  '<tr><td style="background:#000;padding:20px;text-align:center;"><img src="' + logo + '" style="max-width:160px;" alt="Jeffway"></td></tr>',
  '<tr><td style="padding:20px 24px 8px;"><h2 style="margin:0;color:#111;">JIS EasyBOP Filler — Daily Summary</h2>',
  '<p style="color:#777;font-size:13px;margin:8px 0 0;">' + esc(reportDate) + ' (Europe/London)</p></td></tr>',
  '<tr><td style="padding:8px 24px 24px;">',
  '<p style="font-size:13px;color:#444;margin:0 0 12px;">Job Instruction Sheets filled on EasyBOP today (works_id navigation).</p>',
  '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:12px;">',
  '<tr style="background:#f3f3f3;">',
  '<th align="left" style="padding:8px;">#</th>',
  '<th align="left" style="padding:8px;">Q1.3 (CORF)</th>',
  '<th align="left" style="padding:8px;">Works ID</th>',
  '<th align="left" style="padding:8px;">Q1.2 Address</th>',
  '<th align="left" style="padding:8px;">Status</th>',
  '</tr>',
  jobRows,
  '</table></td></tr>',
  '<tr><td style="background:#f9f9f9;padding:16px;text-align:center;font-size:12px;color:#777;">Jeffway Group · Automated JIS EasyBOP filler</td></tr>',
  '</table></td></tr></table></body></html>',
].join('');

return [{
  json: {
    _alert_subject: 'Jeffway — JIS filled on EasyBOP — ' + reportDate + ' (' + logs.length + ')',
    _alert_html: html,
    jis_count: logs.length,
  },
}];
